-- Basic schema for transit stop logs

DROP TABLE IF EXISTS transit_data;

CREATE TABLE transit_data (
    trip_id VARCHAR(50),
    route_id VARCHAR(50),
    stop_id VARCHAR(50),
    stop_sequence INT,
    scheduled_arrival TIMESTAMP,
    actual_arrival TIMESTAMP,
    delay_seconds INT,
    passenger_load INT,
    delay_reason VARCHAR(100)
);

-- Note: You can import the CSV file generated by python into this table
-- using your SQL client's import tool or a COPY command.
